answer = []
for source, (file, reason, notes) in zip(sources, drafts, strict=True):
    item = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(
        proposed_xml=Path('fragments', file).read_text().strip(),
        reason=reason,
        review_notes=notes,
        status='rewrite_draft',
    )
    answer.append(item)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
